// ---------------------------------------------------------------------------
// Classify each user into a funnel stage based on their MOST RECENT event.
//
// Input : one item per row from the "Events" Google Sheet
//         -> { user_id, name, email, event_type, timestamp }
// Output: one item per unique user_id -> adds a `stage` field
// ---------------------------------------------------------------------------

// Flatten incoming items down to plain event objects.
const events = items.map(item => item.json);

// Track the latest-seen event per user_id.
// Map key   -> user_id
// Map value -> { user_id, name, email, latest_event, latestTime, timestamp }
const latestByUser = new Map();

for (const event of events) {
  const { user_id, name, email, event_type, timestamp } = event;
  const eventTime = new Date(timestamp).getTime();

  const existing = latestByUser.get(user_id);

  // Keep this row if it's the first event we've seen for this user,
  // or if its timestamp is newer than what we currently have stored.
  // This is the "latest event wins" rule.
  if (!existing || eventTime > existing.latestTime) {
    latestByUser.set(user_id, {
      user_id,
      name,
      email,
      latest_event: event_type,
      latestTime: eventTime,
      timestamp,
    });
  }
}

// Map a user's single most recent event type directly to a funnel stage.
// Because we already reduced each user down to ONE (their latest) event,
// this is a simple 1:1 lookup rather than a multi-condition rule set:
//   - latest event is a fresh signup with nothing after it -> not_activated
//   - latest event is first_generation (they tried the product, no payment yet) -> activated_not_paid
//   - latest event is payment -> paid
//   - latest event is inactive_3d (fired by a separate scheduled job
//     whenever a user goes quiet for 3 days) -> at_risk, even if they had
//     paid before - inactivity always takes priority as the most recent signal
function classify(eventType) {
  switch (eventType) {
    case 'payment':
      return 'paid';
    case 'inactive_3d':
      return 'at_risk';
    case 'first_generation':
      return 'activated_not_paid';
    case 'signup':
    default:
      return 'not_activated';
  }
}

const results = [];
for (const user of latestByUser.values()) {
  results.push({
    json: {
      user_id: user.user_id,
      name: user.name,
      email: user.email,
      latest_event: user.latest_event,
      timestamp: user.timestamp,
      stage: classify(user.latest_event),
    },
  });
}

return results;

// ---------------------------------------------------------------------------
// Format the final log row for this user.
//
// The Classify Users node is looked up directly (rather than reading
// $json) because $json at this point holds this branch's Groq API
// response, not the original user record. n8n keeps the item-pairing
// intact across Switch/HTTP Request/Merge as long as item count per
// branch doesn't change, so $('Classify Users').item resolves to the
// same user this Groq response belongs to.
// ---------------------------------------------------------------------------
const original = $('Classify Users').item.json;
const groqResponse = $json;

const generatedMessage = groqResponse.choices[0].message.content.trim();

return {
  json: {
    user_id: original.user_id,
    stage: original.stage,
    generated_message: generatedMessage,
    timestamp: new Date().toISOString(),
  },
};
